const tabId = 787784465;

// Let's inspect the text inside the editor iframe
const textInDoc = await browserjs(tabId, () => {
  // Let's find iframe elements
  const iframes = Array.from(document.querySelectorAll('iframe'));
  let found = [];
  for (let f of iframes) {
    try {
      const doc = f.contentDocument || f.contentWindow?.document;
      if (doc && doc.body) {
        found.push({
          src: f.src,
          name: f.name,
          textLen: doc.body.innerText.length,
          snippet: doc.body.innerText.slice(0, 300)
        });
      }
    } catch(e) {
      found.push({ error: e.message, src: f.src });
    }
  }
  return found;
});
console.log("Found in iframes:", JSON.stringify(textInDoc, null, 2));

